-- ── посты ──
insert into public.posts (slug, title, subtitle, category_id, cover, badges, blocks, read_min, published, sort_order) values (
  'apple-design-skill', 'Интерфейс по правилам Apple', 'Скилл apple-design находит в готовом приложении то, что вы перестали замечать', 'ai',
  '{"from":"#4C6FFF","to":"#0B1026","pattern":"waves"}'::jsonb, array['new', 'free'], '[{"type":"text","text":"apple-design — сторонний скилл для Claude Code, собранный по открытым докладам Apple о дизайне. Он объясняет Claude, какими должны быть кнопки, жесты и анимации, чтобы интерфейс отвечал на касание сразу, а не через полсекунды."},{"type":"text","text":"Главное правило: не начинайте с пустого проекта. Ставьте скилл в приложение, которое уже работает, — тогда Claude найдёт то, к чему вы привыкли и на что больше не смотрите."},{"type":"callout","tone":"info","text":"Из подготовки нужен только рабочий проект и установленный Claude Code."},{"type":"heading","text":"1. Откройте проект"},{"type":"text","text":"Откройте приложение в редакторе и перейдите в его папку в терминале."},{"type":"command","command":"cd путь-к-проекту"},{"type":"heading","text":"2. Поставьте скилл"},{"type":"command","command":"npx skills@latest add emilkowalski/skills","note":"Установщик задаст три вопроса."},{"type":"code","lang":"text","code":"Skill: apple-design\nAgent: Claude Code\nScope: Project"},{"type":"text","text":"Scope: Project означает, что скилл останется внутри этого приложения и не попадёт в остальные проекты."},{"type":"heading","text":"3. Перезапустите Claude Code"},{"type":"command","command":"claude","note":"Новый скилл подхватывается только при запуске."},{"type":"heading","text":"4. Попросите аудит"},{"type":"text","text":"Сначала — только разбор, без правок. Иначе Claude начнёт менять интерфейс раньше, чем вы поймёте, что именно с ним не так."},{"type":"prompt","title":"Аудит интерфейса","text":"Используй apple-design skill.\n\nПроверь интерфейс этого проекта по правилам скилла.\n\nПока ничего не изменяй. Сначала покажи пять главных проблем.\n\nДля каждой проблемы укажи:\n- компонент или файл;\n- что работает неправильно;\n- какое правило нарушено;\n- как это исправить."},{"type":"callout","tone":"warning","text":"«Пока ничего не изменяй» — не вежливость, а страховка. Список из пяти пунктов вы правите словами за минуту, переделанный интерфейс придётся откатывать."},{"type":"heading","text":"5. Примените исправления"},{"type":"text","text":"Из аудита берите не всё сразу. Три пункта за раз — столько ещё можно проверить глазами."},{"type":"prompt","title":"Точечные правки","text":"Исправь три самые важные проблемы из аудита.\n\nНе переделывай весь дизайн.\nСохрани текущую цветовую палитру и структуру приложения.\nПосле изменений запусти проект и проверь результат."},{"type":"text","text":"Дальше цикл повторяется: аудит, три правки, проверка. Так интерфейс подтягивается по частям, и на каждом шаге видно, что именно изменилось."},{"type":"heading","text":"Что в итоге"},{"type":"list","ordered":true,"items":["Открыть готовый проект в терминале.","Поставить apple-design со scope Project.","Перезапустить Claude Code.","Запросить аудит без правок.","Исправить три пункта и проверить результат."]},{"type":"callout","tone":"success","text":"Репозиторий скиллов: github.com/emilkowalski/skills. Кроме apple-design там есть и другие — устанавливаются той же командой."}]'::jsonb, 3, true, 0
) on conflict (slug) do update set
  title = excluded.title, subtitle = excluded.subtitle, category_id = excluded.category_id,
  cover = excluded.cover, badges = excluded.badges, blocks = excluded.blocks,
  read_min = excluded.read_min, sort_order = excluded.sort_order;

commit;
